async function init(){if(!state.token)return;try{[state.user,state.meta]=await Promise.all([api('/api/auth/me'),api('/api/metadata')]);aiStatus.textContent=state.meta.ai.enabled?`真实模型 · ${state.meta.ai.model}`:'检索模式 · 未配置模型';showApp()}catch{logout(false)}}
