function metric(label,value,note,cls){return `<div class="metric-card ${cls}"><span>${label}</span><strong>${value}</strong><small>${note}</small></div>`}
function renderRecentTasks(tasks){taskWorkspace.innerHTML=`<div class="section-title"><div><h2>最近 Agent 任务</h2><p>所有任务过程、结果和失败原因均来自数据库</p></div></div><section class="surface"><div class="compact-list">${tasks.map(t=>`<button class="brief-item" data-task="${t.id}" style="border:0;background:#fff;text-align:left"><span class="brief-dot"></span><div><b>${esc(t.input_text)}</b><p>${esc(label(intentLabels,t.intent))} · ${esc(label(statusLabels,t.status))} · ${t.progress}%</p></div></button>`).join('')}</div></section>`;$$('[data-task]').forEach(b=>b.onclick=()=>pollTask(b.dataset.task))}
