const intentLabels={schedule_create:'创建排班方案',schedule_query:'查询班表',leave_request:'请假申请',swap_request:'换班申请',adjust_request:'调整班次',preference_update:'更新排班偏好',attendance_query:'查询考勤',employee_query:'查询员工信息',rule_query:'查询规则',anomaly_query:'查询异常',general_wfm:'一般咨询'};
