function formatParameterValue(key,value){if(key==='demand_items'&&Array.isArray(value))return value.map(item=>`${item.role} ${item.headcount} 名`).join('、');if(typeof value==='boolean')return value?'是':'否';if(Array.isArray(value))return value.join('、');return value}
