function label(map,value){return map[value]||value||'—'}
function panelKey(taskId,panel){return `${taskId}:${panel}`}
function panelToggle(taskId,panel,title,meta){const collapsed=Boolean(state.collapsedPanels[panelKey(taskId,panel)]);return `<button type="button" class="panel-toggle" data-toggle-panel="${panel}" data-task-id="${esc(taskId)}" aria-expanded="${!collapsed}"><span><b>${esc(title)}</b>${meta?`<small>${esc(meta)}</small>`:''}</span><span class="panel-chevron" aria-hidden="true">⌃</span></button>`}
function renderUnderstanding(task){const payload=task.parameters||{},intentResult=payload.intent_result||{},answer=payload.answer||{},parameters=intentResult.parameters||payload,summary=intentResult.summary||task.steps?.[0]?.business_message||'Agent 正在理解业务目标。',intent=intentResult.intent||task.intent,confidence=intentResult.confidence,mode=intentResult.mode||answer.mode,items=Object.entries(parameters).filter(([key,value])=>!['intent_result','answer','raw_constraints'].includes(key)&&value!==null&&value!==''&&value!==undefined&&(!Array.isArray(value)||value.length)),collapsed=Boolean(state.collapsedPanels[panelKey(task.id,'understanding')]);const needsInput=intent==='general_wfm'&&items.length===0;return `<section class="surface understanding-panel"><div class="surface-head collapsible-head">${panelToggle(task.id,'understanding','AI 理解结果','已将自然语言转换为可执行的业务信息')}<span class="badge ${needsInput?'amber':'green'}">${esc(intentLabels[intent]||intent)}</span></div><div class="surface-body collapsible-body" ${collapsed?'hidden':''}><div class="understanding-summary"><span class="understanding-mark">${needsInput?'?':'✓'}</span><div><b>${esc(summary)}</b><p>${needsInput?'尚未识别到具体业务目标，请补充门店、日期、人力需求或需要办理的事务。':'请确认以下理解是否符合你的业务目标。'}</p></div></div>${items.length?`<div class="understanding-fields">${items.map(([key,value])=>`<div><span>${esc(parameterLabels[key]||key)}</span><b>${esc(formatParameterValue(key,value))}${['coverage_target','cost_increase_limit'].includes(key)?'%':''}</b></div>`).join('')}</div>`:''}${answer.answer?`<div class="agent-answer"><span>AI 回复</span><p>${esc(answer.answer)}</p></div>`:''}${task.error?`<p class="form-error">${esc(task.error)}</p>`:''}<details class="technical-details"><summary>查看技术详情</summary><div class="technical-meta"><span>运行模式：${esc(mode||'处理中')}</span>${confidence!==undefined?`<span>意图置信度：${Math.round(Number(confidence)*100)}%</span>`:''}</div><pre>${esc(JSON.stringify(payload,null,2))}</pre></details></div></section>`}
function renderTask(task){const host=$('#taskWorkspace')||content,stepsCollapsed=Boolean(state.collapsedPanels[panelKey(task.id,'steps')]);host.innerHTML=`<div class="section-title"><div><h2>Agent 执行轨迹</h2><p>${esc(task.input_text)}</p></div><span class="badge ${task.status==='failed'?'red':task.status==='completed'?'green':'blue'}">${esc(label(statusLabels,task.status))} · ${task.progress}%</span></div><div class="hero-grid"><section class="surface"><div class="surface-head collapsible-head">${panelToggle(task.id,'steps','六阶段决策过程',`${task.steps.length} / 6`)}</div><div class="surface-body timeline collapsible-body" ${stepsCollapsed?'hidden':''}>${task.steps.map(s=>`<div class="timeline-item"><span class="timeline-index ${s.status==='running'?'running':''}">${s.stage}</span><div class="timeline-content"><b>${esc(s.name)}</b><p>${esc(s.business_message)}</p><details class="step-technical"><summary>技术信息</summary><span class="technical">${esc(s.technical_message)}</span></details></div></div>`).join('')||'<div class="empty">任务正在进入队列</div>'}<div class="progress"><span style="width:${task.progress}%"></span></div></div></section>${renderUnderstanding(task)}</div>${task.plans?.length?renderPlanCards(task.plans):''}`}
function renderPlanCards(plans){return `<div class="section-title"><div><h2>两套差异化方案</h2><p>推荐不等于生效，生效不等于发布</p></div></div><div class="plan-grid">${plans.map(p=>{const valid=p.valid!==false&&p.metrics.required>0&&p.shifts.length>0;return `<article class="plan-card ${p.recommended&&valid?'recommended':''} ${valid?'':'invalid'}"><div class="plan-title"><div><h3>${esc(p.name)}</h3><span class="supporting-text">${p.solver==='cp_sat'?'约束优化引擎':'启发式优化引擎'}</span></div><span class="badge ${p.recommended&&valid?'green':valid?'':'red'}">${valid?(p.recommended?'AI 推荐':esc(label(statusLabels,p.status))):'无效空方案'}</span></div><div class="plan-metrics"><div><span>覆盖率</span><b>${p.metrics.coverage}%</b></div><div><span>偏好满足</span><b>${p.metrics.preference_rate}%</b></div><div><span>预计成本</span><b>${money(p.metrics.cost)}</b></div></div><p class="plan-facts">${valid?(p.explanation.facts||[]).map(esc).join(' · '):'该历史方案没有岗位需求或班次，不能推荐、生效或发布，请重新运行 Agent。'}</p><div class="action-row">${valid?`<button class="button" data-plan-detail="${p.id}">查看班次</button>${p.status==='active'?`<button class="button primary" data-publish="${p.id}">合规复核并发布</button>`:p.status==='published'?'<span class="badge green">已发布</span>':`<button class="button dark" data-activate="${p.id}">选择生效</button>`}`:'<span class="badge red">请重新生成</span>'}</div></article>`}).join('')}</div>`}
document.addEventListener('click',async e=>{const toggle=e.target.closest('[data-toggle-panel]');if(toggle){toggleCollapsiblePanel(toggle,state.collapsedPanels);return}const context=e.target.closest('[data-plan-detail]');if(context){const plan=state.task.plans.find(x=>x.id===context.dataset.planDetail);openDrawer(plan.name,`<div class="table-wrap"><table><thead><tr><th>员工</th><th>岗位</th><th>开始</th><th>结束</th><th>状态</th></tr></thead><tbody>${plan.shifts.map(s=>`<tr><td>${esc(s.employee_name)}</td><td>${esc(s.role)}</td><td>${esc(s.start_at.slice(0,16).replace('T',' '))}</td><td>${esc(s.end_at.slice(11,16))}</td><td>${esc(label(statusLabels,s.status))}</td></tr>`).join('')}</tbody></table></div>`)}const activate=e.target.closest('[data-activate]');if(activate){state.task=await api(`/api/schedules/${activate.dataset.activate}/activate`,{method:'POST'});renderTask(state.task);toast('方案已选择生效，尚未发布')}const publish=e.target.closest('[data-publish]');if(publish){state.task=await api(`/api/schedules/${publish.dataset.publish}/publish`,{method:'POST'});renderTask(state.task);toast('合规复核通过，班表已发布')}});
function currentMonthRange(){const now=new Date(),year=now.getFullYear(),month=now.getMonth();return [`${year}-${String(month+1).padStart(2,'0')}-01`,`${year}-${String(month+1).padStart(2,'0')}-${String(new Date(year,month+1,0).getDate()).padStart(2,'0')}`]}
async function renderSchedules(){const [start,end]=currentMonthRange(),shifts=await api(`/api/schedules/history?start=${start}&end=${end}`);content.innerHTML=`<div class="schedule-page"><div class="schedule-heading"><div><span class="eyebrow dark">当前排班方案</span><h2>智能班表</h2></div><div class="schedule-toolbar"><label>开始日期<input id="scheduleStart" type="date" value="${start}"></label><label>结束日期<input id="scheduleEnd" type="date" value="${end}"></label><button id="scheduleFilter" class="button primary">查询历史</button><span class="schedule-hint">默认展示本月，方案选择与发布请在 AI 指挥台完成</span></div></div>${scheduleSummary(shifts)}<section class="surface schedule-surface"><div class="schedule-legend"><span><i class="shift-dot morning"></i>白班</span><span><i class="shift-dot evening"></i>晚班</span><span><i class="shift-dot split"></i>中班</span><span><i class="shift-dot other"></i>其他班次</span><span><i class="shift-dot rest"></i>休息</span><span class="schedule-state">已发布班次 · ${shifts.length} 条</span></div><div class="table-wrap" id="scheduleRows">${scheduleMatrix(shifts,start,end)}</div></section></div>`;scheduleFilter.onclick=async()=>{const next=await api(`/api/schedules/history?start=${scheduleStart.value}&end=${scheduleEnd.value}`);scheduleRows.innerHTML=scheduleMatrix(next,scheduleStart.value,scheduleEnd.value);const summary=document.querySelector('.schedule-summary');if(summary)summary.outerHTML=scheduleSummary(next)}}
function scheduleDates(start,end){const dates=[];for(let cursor=new Date(`${start}T00:00:00`),last=new Date(`${end}T00:00:00`);cursor<=last&&dates.length<31;cursor.setDate(cursor.getDate()+1))dates.push(new Date(cursor));return dates}
function scheduleSummary(shifts){const employees=new Set(shifts.map(s=>s.employee_id)).size,days=new Set(shifts.map(s=>s.start_at.slice(0,10))).size;return `<div class="schedule-summary"><div><span>覆盖率</span><b>${shifts.length?Math.min(100,Math.round(employees?shifts.length/(employees*7)*100:0)):'—'}%</b></div><div><span>已排班员工</span><b>${employees} 人</b></div><div><span>工作日覆盖</span><b>${days} 天</b></div><div><span>方案状态</span><b class="schedule-waiting">${shifts.length?'已发布':'等待选择'}</b></div><div class="schedule-mode">当前视图：均衡最优</div></div>`}
function scheduleShiftType(shift){const start=shift.start_at.slice(11,16),end=shift.end_at.slice(11,16),hours=(new Date(`2000-01-01T${end}:00`)-new Date(`2000-01-01T${start}:00`))/3600000;if(start===end||shift.source?.includes('shift-rest'))return 'rest';if(start>='12:00'&&end>='20:00')return 'evening';if(start>='10:00'||hours<8)return 'split';return 'morning'}
function scheduleMatrix(shifts,start,end){const dates=scheduleDates(start,end),byEmployee=new Map();shifts.forEach(shift=>{const key=shift.employee_id;if(!byEmployee.has(key))byEmployee.set(key,{name:shift.employee_name,code:shift.employee_code,role:shift.role,shifts:{}});byEmployee.get(key).shifts[shift.start_at.slice(0,10)]=shift});if(!byEmployee.size)return '<div class="empty">当前月份暂无已发布班次。</div>';return `<table class="schedule-matrix monthly"><thead><tr><th class="employee-heading">员工 / 技能</th>${dates.map(date=>`<th>${['周日','周一','周二','周三','周四','周五','周六'][date.getDay()]} <small>${date.getMonth()+1}/${date.getDate()}</small></th>`).join('')}</tr></thead><tbody>${[...byEmployee.values()].map(employee=>`<tr><td class="schedule-employee"><span class="avatar">${esc(employee.name.slice(0,1))}</span><span><b>${esc(employee.name)}</b><small>${esc(employee.role)} · ${esc(employee.code)}</small></span></td>${dates.map(date=>{const key=`${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`,shift=employee.shifts[key];if(!shift)return '<td class="schedule-rest">休息</td>';const type=scheduleShiftType(shift);return `<td class="schedule-shift ${type}"><b>${esc(shift.start_at.slice(11,16))}–${esc(shift.end_at.slice(11,16))}</b><small>${esc(type==='rest'?'休息班':type==='evening'?'晚班':type==='split'?'午班':'早班')} · ${esc(shift.role)}</small></td>`}).join('')}</tr>`).join('')}</tbody></table>`}
async function renderEmployee(){const portal=await api('/api/employee/portal'),name=portal.profile?.name||state.user?.display_name||'同事';content.innerHTML=`<div class="employee-page"><section class="employee-greeting"><span class="eyebrow dark">员工自助服务</span><h2>你好，${esc(name)}。今天想处理什么？</h2><p>可以查询班表、申请请假或换班，也可以告诉我你的排班偏好。</p></section><section class="surface command-surface employee-command"><div class="surface-head"><div><h2>直接告诉我</h2><p>我会识别你的事务，并给出下一步处理结果</p></div><span class="badge green">仅访问本人数据</span></div><div class="surface-body"><textarea id="employeeInput" class="command-input" placeholder="例如：我8月8日有家庭安排，需要请假。"></textarea><div class="employee-examples"><button type="button" data-employee-example="查询我本周的班表">查询班表</button><button type="button" data-employee-example="我8月8日需要请假">申请请假</button><button type="button" data-employee-example="我希望下周尽量排早班">更新偏好</button></div><div class="command-actions"><span class="command-hint">审批前不会修改原班次，申请会生成可跟踪的事务记录</span><button id="runEmployeeAgent" class="button primary">开始处理 →</button></div><div id="employeeResult"></div></div></section><section class="surface employee-profile"><div class="surface-head"><h2>我的档案</h2></div><div class="surface-body">${portal.profile?`<h3>${esc(portal.profile.name)} · ${esc(portal.profile.code)}</h3><p>${esc(portal.profile.role)} / ${esc(portal.profile.store_name)}</p><p class="profile-note">${esc(portal.profile.preferences.ai_summary||'暂无排班偏好')}</p>`:'<div class="empty">当前账号未关联员工档案</div>'}</div></section></div>`;$$('[data-employee-example]').forEach(button=>button.onclick=()=>{employeeInput.value=button.dataset.employeeExample;employeeInput.focus()});runEmployeeAgent.onclick=async()=>{const text=employeeInput.value.trim();if(!text)return toast('请先告诉我你想处理什么事务',true);runEmployeeAgent.disabled=true;try{const result=await api('/api/employee/agent',{method:'POST',body:JSON.stringify({input_text:text})});employeeResult.innerHTML=renderEmployeeResult(result);toast('事务已识别并完成下一步处理')}catch(e){toast(e.message,true)}finally{runEmployeeAgent.disabled=false}}}
function renderEmployeeResult(result){const shifts=result.data?.shifts||[],request=result.data?.request_id;return `<div class="employee-result"><div class="employee-result-head"><span class="badge blue">${esc(label(intentLabels,result.intent?.intent))}</span><b>${esc(result.answer||'已完成识别')}</b></div>${request?`<div class="request-status"><span>申请编号</span><b>${esc(request)}</b><span>状态</span><strong>待主管审批</strong><p>审批完成前，原班次保持不变。你可以稍后在此查看处理结果。</p></div>`:''}${shifts.length?`<div class="employee-shifts"><h3>你的已发布班表</h3><div class="table-wrap"><table><thead><tr><th>日期</th><th>时间</th><th>岗位</th><th>门店</th></tr></thead><tbody>${shifts.map(shift=>`<tr><td>${esc(shift.start_at.slice(0,10))}</td><td><b>${esc(shift.start_at.slice(11,16))}–${esc(shift.end_at.slice(11,16))}</b></td><td>${esc(shift.role)}</td><td>${esc(shift.store_id||'—')}</td></tr>`).join('')}</tbody></table></div></div>`:''}</div>`}
async function renderEmployees(){const employees=await api('/api/organization/employees');content.innerHTML=`<div class="section-title"><div><h2>员工与技能主档</h2><p>技能认证、成本、工时上限和偏好直接参与排班</p></div>${['admin','manager','hr'].includes(state.user.role)?'<button id="addEmployee" class="button primary">新增员工</button>':''}</div><section class="surface"><div class="table-wrap"><table><thead><tr><th>员工</th><th>岗位/部门</th><th>门店</th><th>技能认证</th><th>周工时上限</th><th>时薪</th><th>偏好摘要</th></tr></thead><tbody>${employees.map(e=>`<tr><td><div class="employee-cell"><div class="avatar">${esc(e.name[0])}</div><div><b>${esc(e.name)}</b><small>${esc(e.code)}</small></div></div></td><td>${esc(e.role)}<br><small>${esc(e.department)}</small></td><td>${esc(e.store_name)}</td><td><div class="skill-list">${e.skills.map(s=>`<span class="badge ${s.certified?'green':'amber'}">${esc(s.skill)} L${s.proficiency}</span>`).join('')}</div></td><td>${e.weekly_hour_limit}h</td><td>${money(e.hourly_rate)}</td><td>${esc(e.preferences.ai_summary||'—')}</td></tr>`).join('')}</tbody></table></div></section>`;const add=$('#addEmployee');if(add)add.onclick=openEmployeeForm}
function openEmployeeForm(){const stores=(state.meta?.stores||[]).filter(store=>state.user.role!=='manager'||store.id===state.user.store_id),positions=state.meta?.positions||[],departments=state.meta?.departments||[],skillOptions=state.meta?.skills||[];openDrawer('新增员工',`<form id="employeeForm" class="form-grid"><div class="form-field"><label for="employeeCode">员工工号 *</label><input id="employeeCode" name="code" required maxlength="30" placeholder="例如：FS033"></div><div class="form-field"><label for="employeeName">员工姓名 *</label><input id="employeeName" name="name" required maxlength="50" placeholder="请输入姓名"></div><div class="form-field"><label for="employeeRole">岗位 *</label><select id="employeeRole" name="role" required><option value="">请选择岗位</option>${positions.map(position=>`<option value="${esc(position.name)}" data-department="${esc(position.department)}">${esc(position.name)}</option>`).join('')}</select></div><div class="form-field"><label for="employeeDepartment">部门 *</label><select id="employeeDepartment" name="department" required><option value="">请选择部门</option>${departments.map(department=>`<option value="${esc(department.name)}">${esc(department.name)}</option>`).join('')}</select></div><div class="form-field"><label for="employeeStore">所属门店 *</label><select id="employeeStore" name="store_id" required><option value="">请选择门店</option>${stores.map(store=>`<option value="${esc(store.id)}">${esc(store.name)}（${esc(store.code)}）</option>`).join('')}</select></div><div class="form-field"><label for="employeeType">用工类型</label><select id="employeeType" name="employment_type"><option>全职</option><option>兼职</option><option>小时工</option></select></div><div class="form-field"><label for="employeeHourlyRate">时薪（元）</label><input id="employeeHourlyRate" name="hourly_rate" type="number" min="0" step="0.01" value="35"></div><div class="form-field"><label for="employeeWeeklyHours">周工时上限</label><input id="employeeWeeklyHours" name="weekly_hour_limit" type="number" min="1" max="168" value="40"></div><div class="form-field full"><label for="employeeSkills">技能认证（可多选）</label><select id="employeeSkills" name="skills" class="multi-select" multiple required>${skillOptions.map(skill=>`<option value="${esc(skill.name)}">${esc(skill.name)} · ${esc(skill.category)}</option>`).join('')}</select><small class="field-hint">按住 Command（Mac）或 Ctrl（Windows）可选择多个技能</small></div><div class="form-field full"><label for="employeePreference">排班偏好</label><textarea id="employeePreference" name="preference" placeholder="例如：优先早班，周三不可排班"></textarea></div><p id="employeeFormError" class="form-error full" aria-live="polite"></p><div class="action-row full"><button type="button" class="button" id="cancelEmployee">取消</button><button type="submit" class="button primary" id="saveEmployee">保存员工</button></div></form>`);$('#employeeRole').onchange=event=>{const option=event.target.selectedOptions[0];if(option?.dataset.department)$('#employeeDepartment').value=option.dataset.department};$('#cancelEmployee').onclick=closeDrawer;$('#employeeForm').onsubmit=async event=>{event.preventDefault();const form=event.currentTarget,error=$('#employeeFormError'),submit=$('#saveEmployee');error.textContent='';if(!form.reportValidity())return;submit.disabled=true;const formData=new FormData(form),values=Object.fromEntries(formData);const skills=formData.getAll('skills').map(skill=>({skill,proficiency:3,target_level:3,certified:true,evidence:'主管新增员工时录入'}));const body={code:values.code.trim(),name:values.name.trim(),role:values.role,department:values.department,store_id:values.store_id,employment_type:values.employment_type,hourly_rate:Number(values.hourly_rate),weekly_hour_limit:Number(values.weekly_hour_limit),preferences:values.preference.trim()?{ai_summary:values.preference.trim()}: {},skills};try{await api('/api/organization/employees',{method:'POST',body:JSON.stringify(body)});closeDrawer();toast(`员工 ${body.name} 已新增`);await renderEmployees()}catch(exception){error.textContent=exception.message;submit.disabled=false}}}
async function renderAttendance(){const start='2026-08-01',end='2026-08-07',d=await api(`/api/attendance/overview?start=${start}&end=${end}`),dates=[...new Set(d.records.map(x=>x.event_date))];const map=new Map(d.records.map(x=>[`${x.employee_id}-${x.event_date}`,x]));content.innerHTML=`<div class="metric-grid">${metric('到岗率',d.summary.attendance_rate+'%','正常与迟到到岗','')}${metric('出勤异常',d.summary.exceptions,'仅迟到与缺勤','amber')}${metric('请假记录',d.summary.leave_records,'统计周期','blue')}${metric('加班工时',d.summary.overtime_hours+'h','不计入异常','')}</div><div class="section-title" style="margin-top:20px"><div><h2>人员 × 日期考勤矩阵</h2><p>员工列与日期表头固定，矩阵独立滚动</p></div></div><section class="surface attendance-shell"><table class="attendance-matrix"><thead><tr><th>员工</th>${dates.map(x=>`<th>${x.slice(5)}</th>`).join('')}</tr></thead><tbody>${d.employees.map(e=>`<tr><td><b>${esc(e.name)}</b><br><small>${esc(e.role)}</small></td>${dates.map(date=>{const r=map.get(`${e.id}-${date}`);return `<td>${r?`<span class="attendance-state ${r.event_type}">${({normal:'正常',late:'迟到',absence:'缺勤',leave:'请假',overtime:'加班'}[r.event_type])}</span>`:'—'}</td>`}).join('')}</tr>`).join('')}</tbody></table></section><div class="section-title" style="margin-top:20px"><div><h2>假期额度</h2><p>独立展示应享、已用、待审批和余额</p></div></div><section class="surface"><div class="table-wrap"><table><thead><tr><th>员工</th><th>假期类型</th><th>应享</th><th>已用</th><th>待审批</th><th>余额</th></tr></thead><tbody>${d.balances.map(b=>`<tr><td>${esc(d.employees.find(e=>e.id===b.employee_id)?.name)}</td><td>${esc(b.leave_type)}</td><td>${b.entitled}</td><td>${b.used}</td><td>${b.pending}</td><td><b>${b.entitled-b.used-b.pending}</b></td></tr>`).join('')}</tbody></table></div></section>`}
async function renderAnomalies(){const data=await api('/api/anomalies');content.innerHTML=`<div class="section-title"><div><h2>可解释异常队列</h2><p>事实、影响、可能原因和 AI 建议严格分开</p></div><span class="badge amber">${data.filter(x=>!['resolved','dismissed'].includes(x.status)).length} 条开放</span></div><div class="anomaly-grid">${data.map(a=>`<article class="anomaly-card"><span class="badge ${a.risk_level==='high'?'red':a.risk_level==='medium'?'amber':'blue'}">${esc(label(riskLabels,a.risk_level))} · ${Math.round(a.confidence*100)}%</span><h3>${esc(a.employee_name)} · ${esc(a.anomaly_type)}</h3><p>${esc(a.impact)}</p><button class="button" data-anomaly="${a.id}">查看证据与处置</button></article>`).join('')}</div>`;$$('[data-anomaly]').forEach(b=>b.onclick=()=>{const a=data.find(x=>x.id===b.dataset.anomaly);openDrawer('异常详情',`<div class="detail-section"><h3>事实证据</h3><ul>${a.evidence.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div><div class="detail-section"><h3>业务影响</h3><p>${esc(a.impact)}</p></div><div class="detail-section"><h3>可能原因（非事实）</h3><ul>${a.possible_causes.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div><div class="detail-section"><h3>AI 建议</h3><ul>${a.suggestions.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div>${['admin','manager','hr'].includes(state.user.role)?`<div class="form-field"><label>处置状态</label><select id="anomalyStatus"><option value="acknowledged">已确认</option><option value="monitoring">持续关注</option><option value="resolved">已处理</option><option value="dismissed">已忽略</option></select></div><div class="form-field" style="margin-top:12px"><label>处置说明</label><textarea id="anomalyNote"></textarea></div><button id="saveAnomaly" class="button primary" style="margin-top:12px">保存处置</button>`:''}`);const save=$('#saveAnomaly');if(save)save.onclick=async()=>{try{await api(`/api/anomalies/${a.id}/status`,{method:'POST',body:JSON.stringify({status:anomalyStatus.value,note:anomalyNote.value})});closeDrawer();toast('异常处置已记录到不可变审计日志');renderAnomalies()}catch(e){toast(e.message,true)}}})}
async function renderInsights(){const data=await api('/api/insights');content.innerHTML=`<div class="section-title"><div><h2>风险与成长机会</h2><p>仅用于支持沟通与发展，不作为惩罚性人事决策依据</p></div><span class="badge">${data.length} 名员工</span></div><div class="anomaly-grid">${data.map(x=>`<article class="anomaly-card"><span class="badge ${x.risk_level==='high'?'red':x.risk_level==='medium'?'amber':'green'}">${esc(label(riskLabels,x.risk_level))} · ${x.risk_score}</span><h3>${esc(x.name)} · ${esc(x.role)}</h3><p>${x.facts.map(esc).join('；')}</p><div class="detail-section"><h3>技能差距</h3><p>${x.skill_gaps.length?x.skill_gaps.map(g=>`${esc(g.skill)} 差 ${g.gap} 级`).join('；'):'当前无显著认证差距'}</p></div><p>${x.suggestions.map(esc).join('；')}</p></article>`).join('')}</div>`}
async function renderReview(){const d=await api('/api/reviews/current');content.innerHTML=`<div class="metric-grid">${metric('预测误差',d.metrics.forecast_mape+'%','越低越准确','blue')}${metric('覆盖率',d.metrics.coverage_rate+'%','已发布班表','')}${metric('到岗率',d.metrics.attendance_rate+'%','当前周期','')}${metric('开放异常',d.metrics.open_anomalies,'需继续闭环','amber')}</div><div class="hero-grid" style="margin-top:18px"><section class="surface"><div class="surface-head"><h2>根因归纳</h2><span class="badge">${esc(d.period)}</span></div><div class="surface-body"><ul>${d.root_causes.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div></section><section class="surface"><div class="surface-head"><h2>策略修正</h2><span class="badge green">数据反哺</span></div><div class="brief-list">${d.improvements.map(x=>`<div class="brief-item ${x.risk==='low'?'success':'warning'}"><span class="brief-dot"></span><div><b>${esc(x.action)}</b><p>${x.risk==='low'?'低风险参数已记录':'影响员工或规则边界，等待终审'} · ${esc(label(statusLabels,x.status))}</p></div></div>`).join('')}</div></section></div>`}
async function renderRules(){const data=await api('/api/rules'),stores=(state.meta?.stores||[]).filter(store=>state.user.role!=='manager'||store.id===state.user.store_id);content.innerHTML=`${['admin','manager','hr'].includes(state.user.role)?`<section class="surface"><div class="surface-head"><h2>自然语言规则治理</h2><span class="badge green">真实 Agent 解析</span></div><div class="surface-body"><textarea id="ruleInput" style="width:100%" placeholder="例如：静安店从8月8日起，周五和周六晚高峰至少安排一名销售技能4级以上员工。"></textarea><div class="rule-create-row"><label>适用门店<select id="ruleStore"><option value="">由 Agent 判断为公司级</option>${stores.map(store=>`<option value="${esc(store.id)}">${esc(store.name)}</option>`).join('')}</select></label><button id="createRule" class="button primary">分析冲突与影响 →</button></div><div id="ruleResult"></div></div></section>`:''}<div class="section-title"><div><h2>规则知识库</h2><p>公司级、门店级和临时规则统一治理</p></div></div><section class="surface"><div class="table-wrap"><table><thead><tr><th>规则</th><th>范围</th><th>适用门店</th><th>有效期</th><th>强度</th><th>业务域</th><th>状态</th><th>版本</th><th>来源</th><th>操作</th></tr></thead><tbody>${data.map(r=>`<tr><td><b>${esc(r.name)}</b><br><small>${esc(r.description)}</small></td><td>${esc(label(ruleLabels,r.scope))}</td><td>${r.scope==='store'?esc(r.store_name||'未指定'):'全部门店'}</td><td>${r.scope==='store'?`${esc(r.effective_from)} 起<br><small>${r.effective_to?`至 ${esc(r.effective_to)}`:'长期有效'}</small>`:'—'}</td><td><span class="badge ${r.strength==='hard'?'red':r.strength==='soft'?'amber':'blue'}">${esc(label(ruleLabels,r.strength))}</span></td><td>${esc(label(ruleLabels,r.domain))}</td><td>${esc(label(statusLabels,r.status))}</td><td>V${r.version}</td><td>${esc(label(ruleLabels,r.source))}</td><td>${['admin','manager','hr'].includes(state.user.role)?`<button class="button" data-edit-rule="${r.id}">编辑</button>`:'—'}</td></tr>`).join('')}</tbody></table></div></section>`;const create=$('#createRule');if(create)create.onclick=async()=>{try{const result=await api('/api/rules',{method:'POST',body:JSON.stringify({text:ruleInput.value,store_id:ruleStore.value||null})});ruleResult.innerHTML=`<div class="inline-result"><b>${esc(result.rule.name)}</b><p>解析方式：${result.mode==='live_llm'?'真实模型':'本地规则解析'} · 影响员工 ${result.impact.employees} 人 · 影响正式班次 ${result.impact.shifts} 个</p><p>${result.rule.scope==='store'?`有效期：${esc(result.rule.effective_from)} 起，${result.rule.effective_to?`${esc(result.rule.effective_to)} 失效`:'长期有效'}`:''}</p><p>${result.analysis.conflicts.length?'冲突：'+result.analysis.conflicts.map(esc).join('；'):'未识别到直接冲突'}</p></div>`;toast('规则已写入数据库');await renderRules()}catch(e){toast(e.message,true)}};$$('[data-edit-rule]').forEach(button=>button.onclick=()=>openRuleEditor(data.find(rule=>rule.id===button.dataset.editRule)))}
function openRuleEditor(rule){const stores=(state.meta?.stores||[]).filter(store=>state.user.role!=='manager'||store.id===state.user.store_id);openDrawer('编辑规则',`<form id="ruleEditForm" class="form-grid"><div class="form-field full"><label>规则名称</label><input name="name" required value="${esc(rule.name)}"></div><div class="form-field full"><label>规则说明</label><textarea name="description" required>${esc(rule.description)}</textarea></div><div class="form-field"><label>适用范围</label><select id="editRuleScope" name="scope"><option value="company" ${rule.scope==='company'?'selected':''}>公司级</option><option value="store" ${rule.scope==='store'?'selected':''}>门店级</option><option value="temporary" ${rule.scope==='temporary'?'selected':''}>临时规则</option></select></div><div class="form-field"><label>适用门店</label><select id="editRuleStore" name="store_id"><option value="">请选择门店</option>${stores.map(store=>`<option value="${esc(store.id)}" ${rule.store_id===store.id?'selected':''}>${esc(store.name)}</option>`).join('')}</select></div><div class="form-field"><label>生效日期</label><input id="editRuleEffectiveFrom" name="effective_from" type="date" value="${esc(rule.effective_from||'')}"></div><div class="form-field"><label>失效日期（留空为长期有效）</label><input id="editRuleEffectiveTo" name="effective_to" type="date" value="${esc(rule.effective_to||'')}"></div><div class="form-field"><label>规则强度</label><select name="strength"><option value="hard" ${rule.strength==='hard'?'selected':''}>硬约束</option><option value="soft" ${rule.strength==='soft'?'selected':''}>软约束</option><option value="notice" ${rule.strength==='notice'?'selected':''}>提示规则</option></select></div><div class="form-field"><label>业务域</label><select name="domain"><option value="schedule" ${rule.domain==='schedule'?'selected':''}>排班管理</option><option value="hours" ${rule.domain==='hours'?'selected':''}>工时管理</option><option value="leave" ${rule.domain==='leave'?'selected':''}>假期管理</option><option value="fatigue" ${rule.domain==='fatigue'?'selected':''}>疲劳风险</option><option value="coverage" ${rule.domain==='coverage'?'selected':''}>岗位覆盖</option><option value="skills" ${rule.domain==='skills'?'selected':''}>技能要求</option></select></div><p id="ruleEditError" class="form-error full"></p><div class="action-row full"><button type="button" id="cancelRuleEdit" class="button">取消</button><button type="submit" id="saveRuleEdit" class="button primary">保存新版本</button></div></form>`);const syncStore=()=>{const enabled=$('#editRuleScope').value==='store';$('#editRuleStore').disabled=!enabled;$('#editRuleEffectiveFrom').disabled=!enabled;$('#editRuleEffectiveTo').disabled=!enabled};syncStore();$('#editRuleScope').onchange=syncStore;$('#cancelRuleEdit').onclick=closeDrawer;$('#ruleEditForm').onsubmit=async event=>{event.preventDefault();const form=event.currentTarget,values=Object.fromEntries(new FormData(form)),submit=$('#saveRuleEdit'),error=$('#ruleEditError');error.textContent='';submit.disabled=true;try{await api(`/api/rules/${rule.id}`,{method:'PUT',body:JSON.stringify(values)});closeDrawer();toast('规则新版本已保存');await renderRules()}catch(exception){error.textContent=exception.message;submit.disabled=false}}}
async function renderAutomation(){const data=await api('/api/automation/events');content.innerHTML=`${['admin','manager','hr'].includes(state.user.role)?`<section class="surface"><div class="surface-head"><h2>接入业务事件</h2><span class="badge">自动重排不自动发布</span></div><div class="surface-body form-grid"><div class="form-field"><label>事件类型</label><select id="eventType"><option value="demand_spike">客流/订单突增</option><option value="employee_unavailable">员工不可用</option><option value="absence_reported">缺勤上报</option><option value="leave_approved">请假批准</option><option value="shift_vacancy">班次空缺</option></select></div><div class="form-field"><label>事件唯一标识</label><input id="eventKey" value="external-${Date.now()}"></div><div class="form-field full"><label>事件原始数据（JSON）</label><textarea id="eventPayload">{"forecast":980,"actual":1210,"date":"2026-08-08","role":"导购"}</textarea></div><div class="form-field full"><button id="createEvent" class="button primary">写入事件队列</button></div></div></section>`:''}<div class="section-title"><div><h2>自动事件队列</h2><p>按优先级与创建时间处理，失败不无限重试</p></div></div><section class="surface"><div class="table-wrap"><table><thead><tr><th>类型</th><th>优先级</th><th>状态</th><th>尝试次数</th><th>关联任务</th><th>创建时间</th><th>错误</th></tr></thead><tbody>${data.map(e=>`<tr><td>${esc(label(eventLabels,e.event_type))}</td><td>${e.priority}</td><td><span class="badge ${e.status==='completed'?'green':e.status==='failed'?'red':'blue'}">${esc(label(statusLabels,e.status))}</span></td><td>${e.attempts}</td><td>${esc(e.task_id||'—')}</td><td>${esc(e.created_at.slice(0,19))}</td><td>${esc(e.error||'—')}</td></tr>`).join('')}</tbody></table></div></section>`;const create=$('#createEvent');if(create)create.onclick=async()=>{try{await api('/api/automation/events',{method:'POST',body:JSON.stringify({event_type:eventType.value,dedupe_key:eventKey.value,store_id:state.user.store_id||'store-a',payload:JSON.parse(eventPayload.value)})});toast('事件已进入自动监听队列');setTimeout(renderAutomation,1200)}catch(e){toast(e.message,true)}}}
async function renderAudit(){const data=await api('/api/audit');content.innerHTML=`<div class="section-title"><div><h2>不可变操作审计</h2><p>登录、AI 调用、任务、发布、规则、异常和自动事件均留痕</p></div>${state.user.role==='admin'?'<button id="createBackup" class="button primary">创建在线备份</button>':''}</div><section class="surface"><div class="table-wrap"><table><thead><tr><th>时间</th><th>用户</th><th>操作代码</th><th>资源类型</th><th>结果</th><th>请求编号</th></tr></thead><tbody>${data.map(a=>`<tr><td>${esc(a.occurred_at.slice(0,19))}</td><td>${esc(a.user_id||'匿名')}</td><td>${esc(a.action)}</td><td>${esc(label(auditResourceLabels,a.resource_type))}</td><td><span class="badge ${a.result==='success'?'green':'red'}">${esc(label(auditResultLabels,a.result))}</span></td><td>${esc(a.request_id||'—')}</td></tr>`).join('')}</tbody></table></div></section>`;const backup=$('#createBackup');if(backup)backup.onclick=async()=>{try{const result=await api('/api/admin/backups',{method:'POST'});toast(`备份完成：${Math.round(result.size_bytes/1024)} KB`);renderAudit()}catch(e){toast(e.message,true)}}}
function openDrawer(title,html){drawerTitle.textContent=title;drawerBody.innerHTML=html;drawer.hidden=false}function closeDrawer(){drawer.hidden=true}drawerClose.onclick=closeDrawer;drawer.onclick=e=>{if(e.target===drawer)closeDrawer()};document.addEventListener('keydown',e=>{if(e.key==='Escape')closeDrawer()});
function renderEmployeeResult(result){const shifts=result.data?.shifts||[],request=result.data?.request_id,needsConfirmation=result.data?.needs_confirmation;return `<div class="employee-result"><div class="employee-result-head"><span class="badge blue">${esc(label(intentLabels,result.intent?.intent))}</span><b>${esc(result.answer||'已完成识别')}</b></div>${request?`<div class="request-status"><span>申请编号</span><b>${esc(request)}</b><span>状态</span><strong>${needsConfirmation?'待你确认':'待主管审批'}</strong><p>${needsConfirmation?'请确认申请内容无误，确认后才会提交给主管审批。':'审批完成前，原班次保持不变。你可以稍后在此查看处理结果。'}</p>${needsConfirmation?`<button type="button" class="button primary" data-confirm-request="${esc(request)}">确认并提交给主管</button>`:''}</div>`:''}${shifts.length?`<div class="employee-shifts"><h3>你的已发布班表</h3><div class="table-wrap"><table><thead><tr><th>日期</th><th>时间</th><th>岗位</th><th>门店</th></tr></thead><tbody>${shifts.map(shift=>`<tr><td>${esc(shift.start_at.slice(0,10))}</td><td><b>${esc(shift.start_at.slice(11,16))}–${esc(shift.end_at.slice(11,16))}</b></td><td>${esc(shift.role)}</td><td>${esc(shift.store_id||'—')}</td></tr>`).join('')}</tbody></table></div></div>`:''}</div>`}
document.addEventListener('click',async event=>{const button=event.target.closest('[data-confirm-request]');if(!button)return;button.disabled=true;const card=button.closest('.leave-confirmation,.request-status'),payload={leave_date:$('#leaveDate')?.value,leave_type:$('#leaveType')?.value,start_time:$('#leaveStart')?.value,end_time:$('#leaveEnd')?.value};try{await api(`/api/employee/requests/${button.dataset.confirmRequest}/confirm`,{method:'POST',body:JSON.stringify(payload)});if(card){const badge=card.querySelector('.badge');if(badge){badge.textContent='待主管审批';badge.className='badge blue'}button.remove();card.insertAdjacentHTML('beforeend','<p class="confirmation-success">申请已提交给主管审批，审批完成前不会改变原班次。</p>')}toast('申请已提交给主管审批')}catch(error){button.disabled=false;toast(error.message,true)}})
function renderRecentTasks(tasks){taskWorkspace.innerHTML=`<div class="section-title"><div><h2>最近任务</h2><p>每次输入、分析过程、候选方案和发布结果均完整保存</p></div></div><section class="surface recent-tasks">${tasks.map(t=>`<article class="recent-task"><button type="button" class="recent-task-toggle" data-recent-task="${t.id}" aria-expanded="false"><span><b>${esc(t.input_text)}</b><small>${esc(label(intentLabels,t.intent))} · ${esc(label(statusLabels,t.status))} · ${esc(t.created_at.slice(0,16).replace('T',' '))}</small></span><span class="panel-chevron">⌄</span></button><div class="recent-task-detail" data-recent-detail="${t.id}" hidden></div></article>`).join('')}</section>`;$$('[data-recent-task]').forEach(button=>button.onclick=async()=>{const detail=$(`[data-recent-detail="${button.dataset.recentTask}"]`),opening=detail.hidden;button.setAttribute('aria-expanded',String(opening));button.querySelector('.panel-chevron').textContent=opening?'⌃':'⌄';detail.hidden=!opening;if(opening&&!detail.dataset.loaded){detail.innerHTML='<div class="empty">正在读取分析过程和方案…</div>';try{const task=await api(`/api/tasks/${button.dataset.recentTask}`);detail.innerHTML=renderRecentTaskDetail(task);detail.dataset.loaded='true'}catch(error){detail.innerHTML=`<div class="empty">${esc(error.message)}</div>`}}})}
function renderRecentTaskDetail(task){const steps=task.steps||[];return `<div class="recent-task-content"><div class="recent-steps">${steps.map(step=>`<div><span>${step.stage}</span><p><b>${esc(step.name)}</b><br>${esc(step.business_message)}</p></div>`).join('')||'<p>暂无分析过程</p>'}</div>${task.plans?.length?`<div class="recent-results"><h3>最终方案</h3>${task.plans.map(plan=>`<button type="button" data-open-task-plan="${plan.id}" data-task-id="${task.id}"><b>${esc(plan.name)}</b><span>${plan.metrics.coverage}% 覆盖 · ${money(plan.metrics.cost)} · ${esc(label(statusLabels,plan.status))}</span></button>`).join('')}</div>`:`<p>${task.error?esc(task.error):'本次任务没有生成排班方案。'}</p>`}</div>`}

async function renderOverview(){const data=await api('/api/overview'),now=new Date(),name=state.user?.display_name||'同事',store=state.meta?.stores?.find(item=>item.id===state.user?.store_id);content.innerHTML=`<div class="ai-workbench"><aside class="workbench-history surface"><div class="workbench-panel-head"><div><span>任务记录</span><h2>最近任务</h2></div><span class="badge">${data.recent_tasks.length}</span></div><div id="recentTaskList"></div></aside><main class="workbench-main"><section class="workbench-greeting"><div><span>${now.getHours()<12?'早上好':now.getHours()<18?'下午好':'晚上好'}，${esc(name)}</span><h2>今天需要处理什么业务目标？</h2><p>描述活动、客流高峰和控制目标，我会先确认范围，再生成可比较方案。</p></div><span class="badge green">AI 在线</span></section><section class="surface workbench-composer"><div class="context-row">${[['auto','自动识别'],['store_management','门店管理'],['my_affairs','我的事务']].map(item=>`<button class="context-chip ${state.context===item[0]?'active':''}" data-context="${item[0]}">${item[1]}</button>`).join('')}</div><textarea id="commandInput" class="command-input" placeholder="例如：下周末有促销活动，客流高峰在下午和晚上，希望覆盖充足并控制加班和夜班。"></textarea><div class="command-actions"><span class="command-hint">AI 会先确认门店、周期和约束，不会直接发布班表</span><button id="runTask" class="button primary">分析业务目标</button></div></section><section id="taskWorkspace" class="workbench-task"><div class="surface empty workbench-empty">当前没有正在处理的任务</div></section></main><aside class="workbench-rail"><section class="surface rail-section"><div class="workbench-panel-head"><div><span>当前范围</span><h2>决策上下文</h2></div></div><div class="rail-facts"><div><span>登录角色</span><b>${esc(roles[state.user.role])}</b></div><div><span>当前门店</span><b>${esc(store?.name||'待任务确认')}</b></div><div><span>模型状态</span><b>${state.meta.ai.enabled?esc(state.meta.ai.model):'未配置模型'}</b></div><div><span>生效规则</span><b>${data.active_rules} 条</b></div></div></section><section class="surface rail-section"><div class="workbench-panel-head"><div><span>运营状态</span><h2>实时摘要</h2></div></div><div class="rail-metrics"><div><b>${data.employee_count}</b><span>在岗员工</span></div><div><b>${data.attendance_rate}%</b><span>到岗率</span></div><div><b>${data.open_anomalies}</b><span>开放异常</span></div></div></section></aside></div>`;$$('[data-context]').forEach(button=>button.onclick=()=>{state.context=button.dataset.context;$$('[data-context]').forEach(item=>item.classList.toggle('active',item===button))});runTask.onclick=async()=>{const text=commandInput.value.trim();if(!text)return toast('请先描述业务目标',true);setAiBusy(runTask,true,'正在理解业务…');try{const result=await api('/api/tasks',{method:'POST',body:JSON.stringify({input_text:text,context:state.context})});if(result.requires_confirmation)renderScheduleConfirmation(result,text);else pollTask(result.task_id)}catch(error){toast(error.message,true);setAiBusy(runTask,false)}};renderRecentTasks(data.recent_tasks)}
function renderRecentTasks(tasks){const host=$('#recentTaskList');if(!host)return;host.innerHTML=tasks.length?tasks.map(task=>`<article class="workbench-history-item"><button type="button" data-recent-task="${task.id}" aria-expanded="false"><span>${esc(task.input_text)}</span><small>${esc(label(statusLabels,task.status))} · ${esc(task.created_at.slice(5,16).replace('T',' '))}</small></button><div data-recent-detail="${task.id}" hidden></div></article>`).join(''):'<div class="empty">暂无任务</div>';$$('[data-recent-task]').forEach(button=>button.onclick=async()=>{const detail=$(`[data-recent-detail="${button.dataset.recentTask}"]`),opening=detail.hidden;detail.hidden=!opening;button.setAttribute('aria-expanded',String(opening));if(opening&&!detail.dataset.loaded){const task=await api(`/api/tasks/${button.dataset.recentTask}`);detail.innerHTML=renderRecentTaskDetail(task);detail.dataset.loaded='true'}})}
function renderTask(task){const host=$('#taskWorkspace')||content;state.task=task;const params=task.parameters||{},steps=task.steps||[],statusClass=task.status==='failed'?'red':task.status==='completed'?'green':'blue';host.innerHTML=`<section class="surface decision-flow"><div class="decision-head"><div><span class="badge ${statusClass}">${esc(label(statusLabels,task.status))} · ${task.progress}%</span><h2>${esc(task.input_text)}</h2></div>${task.plans?.length?'<button class="button" data-open-schedule>进入智能班表</button>':''}</div><div class="decision-stage"><span>1</span><div><b>AI 业务理解</b><p>${esc(steps[0]?.business_message||'正在识别业务目标和约束')}</p>${Object.keys(params).length?`<div class="decision-tags">${Object.entries(params).filter(([,value])=>value!==null&&value!==''&&(!Array.isArray(value)||value.length)).slice(0,8).map(([key,value])=>`<span>${esc(parameterLabels[key]||key)}：${esc(formatParameterValue(key,value))}</span>`).join('')}</div>`:''}</div></div><div class="decision-stage"><span>2</span><div><b>数据检索与需求预测</b><p>${esc(steps.find(step=>step.stage===3)?.business_message||'等待门店、周期和业务范围确认')}</p></div></div>${task.plans?.length?`<div class="decision-stage"><span>3</span><div><b>方案对比与决策</b><p>比较覆盖率、成本、偏好满足率和风险后，再选择方案。</p></div></div>${renderPlanCards(task.plans)}`:''}<details class="execution-details"><summary>查看 Agent 分析过程（${steps.length} 个阶段）</summary><div class="recent-steps">${steps.map(step=>`<div><span>${step.stage}</span><p><b>${esc(step.name)}</b><br>${esc(step.business_message)}</p></div>`).join('')||'<p>任务正在进入队列</p>'}</div></details>${task.error?`<p class="form-error">${esc(task.error)}</p>`:''}</section>`;const open=host.querySelector('[data-open-schedule]');if(open)open.onclick=()=>navigate('schedules')}

async function renderSchedules(){const [start,end]=currentMonthRange();await loadScheduleWorkspace(start,end)}
async function loadScheduleWorkspace(start,end,taskId=''){const query=`start=${start}&end=${end}${taskId?`&task_id=${encodeURIComponent(taskId)}`:''}`,workspace=await api(`/api/schedules/workspace?${query}`),plans=workspace.plans||[];if(!state.schedulePlanId||!plans.some(plan=>plan.id===state.schedulePlanId))state.schedulePlanId=(plans.find(plan=>plan.recommended)||plans[0])?.id||null;const selected=plans.find(plan=>plan.id===state.schedulePlanId),visibleShifts=selected?.shifts||workspace.published||[];content.innerHTML=`<div class="schedule-page"><div class="schedule-heading"><div><span class="eyebrow dark">AI 排班决策工作区</span><h2>智能班表</h2><p>${workspace.view_mode==='self'?'仅展示当前登录员工的已发布班次。':`排班周期：${start} 至 ${end} · 候选方案与正式班表分开展示。`}</p></div><div class="schedule-toolbar"><label>开始日期<input id="scheduleStart" type="date" value="${start}"></label><label>结束日期<input id="scheduleEnd" type="date" value="${end}"></label><button id="scheduleFilter" class="button">查询</button></div></div>${plans.length?`<section class="surface plan-switcher"><div class="plan-tabs">${plans.map(plan=>`<button type="button" class="plan-tab ${plan.id===state.schedulePlanId?'active':''}" data-schedule-plan="${plan.id}"><b>${esc(plan.name)}</b><span>${plan.metrics.coverage}% 覆盖 · ${money(plan.metrics.cost)}</span>${plan.recommended?'<em>AI 推荐</em>':''}</button>`).join('')}</div>${schedulePlanComparison(plans,selected)}</section>`:'<section class="surface empty">没有可比较的候选方案，下方仅展示已经发布的正式班表。</section>'}${selected?scheduleSummaryForPlan(selected):scheduleSummary(visibleShifts)}<section class="surface schedule-surface"><div class="schedule-legend"><span><i class="shift-dot morning"></i>白班</span><span><i class="shift-dot evening"></i>晚班</span><span><i class="shift-dot split"></i>中班</span><span><i class="shift-dot rest"></i>未排班</span><span class="schedule-state">${selected?`${esc(selected.name)} · ${selected.shifts.length} 个班次`:`已发布班次 · ${visibleShifts.length} 条`}</span></div><div class="table-wrap" id="scheduleRows">${scheduleMatrix(visibleShifts,start,end)}</div></section></div>`;scheduleFilter.onclick=()=>loadScheduleWorkspace(scheduleStart.value,scheduleEnd.value);$$('[data-schedule-plan]').forEach(button=>button.onclick=()=>{state.schedulePlanId=button.dataset.schedulePlan;loadScheduleWorkspace(start,end,workspace.task?.id||'')});const choose=$('#chooseSchedulePlan'),publish=$('#publishSchedulePlan');if(choose)choose.onclick=async()=>{await api(`/api/schedules/${selected.id}/activate`,{method:'POST'});toast('已选择该方案，尚未写入正式班表');await loadScheduleWorkspace(start,end,workspace.task.id)};if(publish)publish.onclick=async()=>{await api(`/api/schedules/${selected.id}/publish`,{method:'POST'});toast('班表已发布并通知相关员工');await loadScheduleWorkspace(start,end,workspace.task.id)}}
function schedulePlanComparison(plans,selected){return `<div class="plan-comparison"><div><span>当前方案</span><b>${esc(selected.name)}</b></div><div><span>覆盖率</span><b>${selected.metrics.coverage}%</b></div><div><span>预计成本</span><b>${money(selected.metrics.cost)}</b></div><div><span>偏好满足</span><b>${selected.metrics.preference_rate}%</b></div><div><span>风险缺口</span><b>${selected.metrics.risk_count||0} 个</b></div><div class="plan-decision">${selected.status==='published'?'<span class="badge green">已发布并通知员工</span>':selected.status==='active'?`<button id="publishSchedulePlan" class="button primary">确认发布班表</button>`:`<button id="chooseSchedulePlan" class="button dark">选择此方案</button>`}</div></div>`}
function scheduleSummaryForPlan(plan){return `<div class="schedule-summary"><div><span>岗位覆盖</span><b>${plan.metrics.assigned}/${plan.metrics.required}</b></div><div><span>覆盖率</span><b>${plan.metrics.coverage}%</b></div><div><span>预计成本</span><b>${money(plan.metrics.cost)}</b></div><div><span>偏好满足</span><b>${plan.metrics.preference_rate}%</b></div><div class="schedule-mode">${esc(label(statusLabels,plan.status))}</div></div>`}
function renderScheduleConfirmation(result,originalText){const stores=result.available_stores||[];taskWorkspace.innerHTML=`<section class="surface confirmation-panel"><div class="surface-head"><div><h2>还需要你确认排班范围</h2><p>我已记录这次输入，但不会替你猜门店或日期。</p></div><span class="badge amber">等待确认</span></div><div class="surface-body form-grid"><div class="form-field full"><label>适用门店</label><select id="confirmStore"><option value="">请选择门店</option>${stores.map(store=>`<option value="${esc(store.code)}">${esc(store.name)}（${esc(store.code)}）</option>`).join('')}</select></div><div class="form-field"><label>开始日期</label><input id="confirmStart" type="date" value="${esc(result.parameters?.start_date||'')}"></div><div class="form-field"><label>结束日期</label><input id="confirmEnd" type="date" value="${esc(result.parameters?.end_date||'')}"></div><p class="form-error full" id="confirmError"></p><div class="action-row full"><button id="confirmSchedule" class="button primary">确认范围并生成整月方案</button></div></div></section>`;confirmSchedule.onclick=async()=>{confirmSchedule.disabled=true;confirmError.textContent='';try{await api(`/api/tasks/${result.task_id}/confirm`,{method:'POST',body:JSON.stringify({store_code:confirmStore.value,start_date:confirmStart.value,end_date:confirmEnd.value})});toast('范围已确认，开始生成整月排班方案');pollTask(result.task_id)}catch(error){confirmError.textContent=error.message;confirmSchedule.disabled=false}}}
function renderEmployeeResult(result){const shifts=result.data?.shifts||[],request=result.data?.request_id,payload=result.data?.payload||{},analysis=result.data?.analysis||{},needsConfirmation=result.data?.needs_confirmation;return `<div class="employee-result"><div class="employee-result-head"><span class="badge blue">${esc(label(intentLabels,result.intent?.intent))}</span><b>${esc(result.answer||'已完成识别')}</b></div>${request?`<div class="leave-confirmation"><h3>请确认请假申请</h3><div class="form-grid"><div class="form-field"><label>请假日期</label><input id="leaveDate" type="date" value="${esc(payload.leave_date||'')}"></div><div class="form-field"><label>假期类型</label><select id="leaveType">${['年假','病假','事假','调休'].map(type=>`<option ${payload.leave_type===type?'selected':''}>${type}</option>`).join('')}</select></div><div class="form-field"><label>开始时间</label><input id="leaveStart" type="time" value="${esc(payload.start_time||'09:00')}"></div><div class="form-field"><label>结束时间</label><input id="leaveEnd" type="time" value="${esc(payload.end_time||'18:00')}"></div></div><div class="leave-analysis"><b>AI 分析过程</b><p>${esc(analysis.leave_type_reason||'根据你的请假原因和假期余额生成建议，提交前可以修改。')}</p>${(analysis.facts||[]).map(fact=>`<span>${esc(fact)}</span>`).join('')}</div><div class="action-row"><span class="badge amber">${needsConfirmation?'待你确认':'待主管审批'}</span>${needsConfirmation?`<button type="button" class="button primary" data-confirm-request="${esc(request)}">确认并提交给主管</button>`:''}</div></div>`:''}${shifts.length?`<div class="employee-shifts"><h3>你的已发布班表</h3><div class="table-wrap"><table><thead><tr><th>日期</th><th>时间</th><th>岗位</th><th>门店</th></tr></thead><tbody>${shifts.map(shift=>`<tr><td>${esc(shift.start_at.slice(0,10))}</td><td><b>${esc(shift.start_at.slice(11,16))}–${esc(shift.end_at.slice(11,16))}</b></td><td>${esc(shift.role)}</td><td>${esc(shift.store_id||'—')}</td></tr>`).join('')}</tbody></table></div></div>`:''}</div>`}
function renderApprovalRequests(requests){if(!requests.length)return '';return `<div class="section-title" style="margin-top:20px"><div><h2>待审批请假</h2><p>员工确认后提交的申请，需要主管明确批准或驳回</p></div><span class="badge amber">${requests.length} 条待处理</span></div><section class="surface"><div class="table-wrap"><table><thead><tr><th>员工</th><th>日期</th><th>假期类型</th><th>时间</th><th>申请原因</th><th>操作</th></tr></thead><tbody>${requests.map(request=>`<tr><td><b>${esc(request.employee_name)}</b><br><small>${esc(request.employee_code)}</small></td><td>${esc(request.payload.leave_date)}</td><td>${esc(request.payload.leave_type)}</td><td>${esc(request.payload.start_time)}–${esc(request.payload.end_time)}</td><td>${esc(request.reason)}</td><td><div class="action-row"><button class="button primary" data-request-decision="${request.id}" data-decision="approved">批准</button><button class="button" data-request-decision="${request.id}" data-decision="rejected">驳回</button></div></td></tr>`).join('')}</tbody></table></div></section>`}
async function renderShiftTemplates(){const templates=await api('/api/shift-templates');content.innerHTML=`<div class="section-title"><div><h2>班次信息</h2><p>统一维护排班可使用的班次模板，智能排班和人工调班都使用这里的定义。</p></div>${['admin','manager','hr'].includes(state.user.role)?'<button id="addShiftTemplate" class="button primary">新增班次</button>':''}</div><section class="surface"><div class="table-wrap"><table><thead><tr><th>班次</th><th>时间</th><th>计薪工时</th><th>类型</th><th>说明</th><th>状态</th><th>操作</th></tr></thead><tbody>${templates.map(template=>`<tr><td><b>${esc(template.name)}</b><br><small>${esc(template.code)}</small></td><td>${esc(template.start_time)}–${esc(template.end_time)}</td><td>${template.paid_hours} 小时</td><td>${esc(template.shift_type==='rest'?'休息班':template.shift_type==='night'?'晚班':'工作班')}</td><td>${esc(template.description||'—')}</td><td><span class="badge ${template.status==='active'?'green':'amber'}">${esc(template.status==='active'?'启用':'停用')}</span></td><td>${['admin','manager','hr'].includes(state.user.role)?`<button class="button" data-edit-shift="${template.id}">编辑</button>`:'—'}</td></tr>`).join('')}</tbody></table></div></section>`;const add=$('#addShiftTemplate');if(add)add.onclick=()=>openShiftTemplateForm();$$('[data-edit-shift]').forEach(button=>button.onclick=()=>openShiftTemplateForm(templates.find(template=>template.id===button.dataset.editShift)))}
function openShiftTemplateForm(template={}){openDrawer(template.id?'编辑班次':'新增班次',`<form id="shiftTemplateForm" class="form-grid"><div class="form-field"><label>班次编码 *</label><input name="code" required value="${esc(template.code||'')}" placeholder="例如 MORNING"></div><div class="form-field"><label>班次名称 *</label><input name="name" required value="${esc(template.name||'')}" placeholder="例如 早班"></div><div class="form-field"><label>开始时间 *</label><input name="start_time" type="time" required value="${esc(template.start_time||'09:00')}"></div><div class="form-field"><label>结束时间 *</label><input name="end_time" type="time" required value="${esc(template.end_time||'17:00')}"></div><div class="form-field"><label>计薪工时</label><input name="paid_hours" type="number" min="0" max="24" step="0.5" value="${template.paid_hours??8}"></div><div class="form-field"><label>班次类型</label><select name="shift_type"><option value="day" ${template.shift_type==='day'?'selected':''}>工作班</option><option value="night" ${template.shift_type==='night'?'selected':''}>晚班</option><option value="rest" ${template.shift_type==='rest'?'selected':''}>休息班</option></select></div><div class="form-field full"><label>说明</label><textarea name="description">${esc(template.description||'')}</textarea></div><p id="shiftTemplateError" class="form-error full"></p><div class="action-row full"><button type="button" id="cancelShiftTemplate" class="button">取消</button><button type="submit" class="button primary">保存班次</button></div></form>`);$('#cancelShiftTemplate').onclick=closeDrawer;$('#shiftTemplateForm').onsubmit=async event=>{event.preventDefault();const body=Object.fromEntries(new FormData(event.currentTarget));try{await api(template.id?`/api/shift-templates/${template.id}`:'/api/shift-templates',{method:template.id?'PUT':'POST',body:JSON.stringify(body)});closeDrawer();toast('班次信息已保存');await renderShiftTemplates()}catch(error){$('#shiftTemplateError').textContent=error.message}}}
const renderAttendanceBase=renderAttendance;renderAttendance=async function(){await renderAttendanceBase();const now=new Date(),start=new Date(now.getFullYear(),now.getMonth(),1).toISOString().slice(0,10),end=new Date(now.getFullYear(),now.getMonth()+1,0).toISOString().slice(0,10),data=await api(`/api/attendance/overview?start=${start}&end=${end}`);content.insertAdjacentHTML('beforeend',renderApprovalRequests(data.approval_requests||[]))}
document.addEventListener('click',async event=>{const decision=event.target.closest('[data-request-decision]');if(!decision)return;decision.disabled=true;try{await api(`/api/employee/requests/${decision.dataset.requestDecision}/decision`,{method:'POST',body:JSON.stringify({status:decision.dataset.decision,note:decision.dataset.decision==='approved'?'主管审批通过':'主管驳回'})});toast(decision.dataset.decision==='approved'?'请假已批准':'请假已驳回');await renderAttendance()}catch(error){decision.disabled=false;toast(error.message,true)}})

document.addEventListener('click',event=>{const open=event.target.closest('[data-open-task-plan]');if(open){state.schedulePlanId=open.dataset.openTaskPlan;navigate('schedules')}const button=event.target.closest('#runTask,#runEmployeeAgent,#createRule,#createEvent');if(button&&!button.disabled){setAiBusy(button,true,button.id==='runTask'?'正在理解业务…':button.id==='runEmployeeAgent'?'正在识别事务…':'正在处理…');const watch=setInterval(()=>{if(!button.disabled){clearInterval(watch);setAiBusy(button,false)}},120)}},true);
function setupWorkbenchHistory(){const root=$('.ai-workbench'),panel=$('.workbench-history'),head=panel?.querySelector('.workbench-panel-head');if(!root||!head||head.dataset.toggleReady)return;head.dataset.toggleReady='true';root.classList.add('history-collapsed');const toggle=document.createElement('button');toggle.type='button';toggle.className='history-toggle';toggle.setAttribute('aria-expanded','false');toggle.setAttribute('aria-label','展开最近任务');toggle.title='展开最近任务';toggle.innerHTML='<span aria-hidden="true">≡</span><small>任务</small>';toggle.onclick=()=>{const expanded=root.classList.toggle('history-expanded');root.classList.toggle('history-collapsed',!expanded);toggle.setAttribute('aria-expanded',String(expanded));toggle.setAttribute('aria-label',expanded?'收起最近任务':'展开最近任务');toggle.title=expanded?'收起最近任务':'展开最近任务';toggle.querySelector('span').textContent=expanded?'‹':'≡'};head.appendChild(toggle)}
const workbenchObserver=new MutationObserver(setupWorkbenchHistory);workbenchObserver.observe(content,{childList:true,subtree:true});
function renderAnomalies(){return api('/api/anomalies').then(data=>{const openCount=data.filter(item=>!['resolved','dismissed'].includes(item.status)).length;content.innerHTML=`<div class="section-title anomaly-heading"><div><span class="eyebrow dark">风险检测范围</span><h2>异常中心</h2><p>连续加班、重复迟到、请假上升，以及后续扩展的缺勤、休息间隔、技能覆盖和门店覆盖异常。</p></div><span class="badge amber">${openCount} 条开放异常</span></div><div class="anomaly-scope"><span><b>连续加班</b>连续天数或近 7 天加班时长达到阈值</span><span><b>重复迟到</b>近 7 天迟到次数和分钟数达到阈值</span><span><b>请假上升</b>近 28 天请假次数明显上升，尊重员工隐私</span></div><div class="anomaly-grid">${data.map(item=>`<article class="anomaly-card"><div class="anomaly-card-top"><span class="badge ${item.risk_level==='high'?'red':item.risk_level==='medium'?'amber':'blue'}">${esc(label(riskLabels,item.risk_level))}</span><span class="anomaly-confidence">置信度 ${Math.round(item.confidence*100)}%</span></div><h3>${esc(item.employee_name)} · ${esc(item.anomaly_type)}</h3><p class="anomaly-status">状态：${esc(label(statusLabels,item.status))}</p><p>${esc(item.impact)}</p><button class="button" data-anomaly="${item.id}">查看证据与处置</button></article>`).join('')}</div>`;$$('[data-anomaly]').forEach(button=>button.onclick=()=>{const item=data.find(entry=>entry.id===button.dataset.anomaly);const current=item.status;openDrawer('异常详情',`<div class="anomaly-detail-meta"><span class="badge ${item.risk_level==='high'?'red':item.risk_level==='medium'?'amber':'blue'}">风险：${esc(label(riskLabels,item.risk_level))}</span><span>置信度 ${Math.round(item.confidence*100)}%</span><span>当前状态：${esc(label(statusLabels,current))}</span></div><div class="detail-section"><h3>事实证据</h3><ul>${item.evidence.map(value=>`<li>${esc(value)}</li>`).join('')}</ul></div><div class="detail-section"><h3>业务影响</h3><p>${esc(item.impact)}</p></div><div class="detail-section possible-cause"><h3>可能原因</h3><small>以下内容是待核实的分析假设，不代表确定事实。</small><ul>${item.possible_causes.map(value=>`<li>${esc(value)}</li>`).join('')}</ul></div><div class="detail-section"><h3>AI 建议</h3><ul>${item.suggestions.map(value=>`<li>${esc(value)}</li>`).join('')}</ul></div>${['admin','manager','hr'].includes(state.user.role)?`<div class="anomaly-action"><div class="form-field"><label>主管处置状态</label><select id="anomalyStatus">${[['open','待确认'],['acknowledged','已确认'],['monitoring','持续关注'],['resolved','已处理'],['dismissed','已忽略']].map(([value,text])=>`<option value="${value}" ${current===value?'selected':''}>${text}</option>`).join('')}</select></div><div class="form-field"><label>处置说明（必填）</label><textarea id="anomalyNote" placeholder="请填写核实结果、采取措施或忽略原因"></textarea></div><button id="saveAnomaly" class="button primary">保存处置并写入审计</button></div>`:''}`);const save=$('#saveAnomaly');if(save)save.onclick=async()=>{try{await api(`/api/anomalies/${item.id}/status`,{method:'POST',body:JSON.stringify({status:$('#anomalyStatus').value,note:$('#anomalyNote').value})});closeDrawer();toast('异常处置已记录到不可变审计日志');renderAnomalies()}catch(error){toast(error.message,true)}}})})}
async function renderAttendanceFiltered(){const name=state.attendanceName||'',code=state.attendanceCode||'',d=await api(`/api/attendance/overview?start=2026-08-01&end=2026-08-07&name=${encodeURIComponent(name)}&code=${encodeURIComponent(code)}`),dates=['2026-08-01','2026-08-02','2026-08-03','2026-08-04','2026-08-05','2026-08-06','2026-08-07'],map=new Map(d.records.map(item=>[`${item.employee_id}-${item.event_date}`,item]));content.innerHTML=`<div class="section-title"><div><span class="eyebrow dark">固定查询窗口</span><h2>考勤与假期</h2><p>仅展示 2026 年 8 月 1 日至 8 月 7 日，可按姓名或工号查询真实记录。</p></div></div><section class="surface attendance-filter"><label>员工姓名<input id="attendanceName" value="${esc(name)}" placeholder="例如：李敏"></label><label>工号<input id="attendanceCode" value="${esc(code)}" placeholder="例如：FS003"></label><button id="attendanceSearch" class="button primary">查询</button><button id="attendanceReset" class="button">重置</button></section><div class="metric-grid">${metric('到岗率',d.summary.attendance_rate+'%','正常与迟到到岗','')}${metric('出勤异常',d.summary.exceptions,'仅迟到与缺勤','amber')}${metric('请假记录',d.summary.leave_records,'查询窗口内','blue')}${metric('加班工时',d.summary.overtime_hours+'h','查询窗口内','')}</div><section class="surface attendance-shell"><div class="surface-head"><h2>人员 × 日期考勤矩阵</h2><span class="badge blue">${d.employees.length} 名员工</span></div><table class="attendance-matrix"><thead><tr><th>员工 / 工号</th>${dates.map(day=>`<th>${day.slice(5)}</th>`).join('')}</tr></thead><tbody>${d.employees.map(employee=>`<tr><td><b>${esc(employee.name)}</b><br><small>${esc(employee.code)} · ${esc(employee.role)}</small></td>${dates.map(day=>{const record=map.get(`${employee.id}-${day}`);return `<td>${record?`<span class="attendance-state ${record.event_type}">${({normal:'正常',late:'迟到',absence:'缺勤',leave:'请假',overtime:'加班'}[record.event_type]||record.event_type)}</span>`:'—'}</td>`}).join('')}</tr>`).join('')||'<tr><td colspan="8" class="empty">没有匹配的考勤记录</td></tr>'}</tbody></table></section><section class="surface"><div class="surface-head"><h2>假期额度</h2><span class="badge">同一查询人员范围</span></div><div class="table-wrap"><table><thead><tr><th>员工</th><th>假期类型</th><th>应享</th><th>已用</th><th>待审批</th><th>余额</th></tr></thead><tbody>${d.balances.map(balance=>`<tr><td>${esc(d.employees.find(employee=>employee.id===balance.employee_id)?.name||'—')}</td><td>${esc(balance.leave_type)}</td><td>${balance.entitled}</td><td>${balance.used}</td><td>${balance.pending}</td><td><b>${balance.entitled-balance.used-balance.pending}</b></td></tr>`).join('')}</tbody></table></div></section>`;$('#attendanceSearch').onclick=()=>{state.attendanceName=$('#attendanceName').value.trim();state.attendanceCode=$('#attendanceCode').value.trim();renderAttendanceFiltered()};$('#attendanceReset').onclick=()=>{state.attendanceName='';state.attendanceCode='';renderAttendanceFiltered()}}
function attendanceDateRange(start,end){const dates=[],cursor=new Date(`${start}T00:00:00`),last=new Date(`${end}T00:00:00`);while(cursor<=last&&dates.length<62){dates.push(cursor.toISOString().slice(0,10));cursor.setDate(cursor.getDate()+1)}return dates}
async function renderAttendanceDynamic(){const start=state.attendanceStart||'2026-08-01',end=state.attendanceEnd||'2026-08-07',name=state.attendanceName||'',code=state.attendanceCode||'',d=await api(`/api/attendance/overview?start=${encodeURIComponent(start)}&end=${encodeURIComponent(end)}&name=${encodeURIComponent(name)}&code=${encodeURIComponent(code)}`),dates=attendanceDateRange(start,end),map=new Map(d.records.map(item=>[`${item.employee_id}-${item.event_date}`,item]));content.innerHTML=`<div class="section-title"><div><span class="eyebrow dark">实时数据库查询</span><h2>考勤与假期</h2><p>按日期范围、员工姓名和工号查询考勤记录，表头随查询范围自动变化。</p></div></div><section class="surface attendance-filter"><label>开始日期<input id="attendanceStart" type="date" value="${esc(start)}"></label><label>结束日期<input id="attendanceEnd" type="date" value="${esc(end)}"></label><label>员工姓名<input id="attendanceName" value="${esc(name)}" placeholder="例如：李敏"></label><label>工号<input id="attendanceCode" value="${esc(code)}" placeholder="例如：FS003"></label><button id="attendanceSearch" class="button primary">查询</button><button id="attendanceReset" class="button">重置</button></section><div class="metric-grid">${metric('到岗率',d.summary.attendance_rate+'%','正常与迟到到岗','')}${metric('出勤异常',d.summary.exceptions,'迟到与缺勤','amber')}${metric('请假记录',d.summary.leave_records,'查询范围内','blue')}${metric('加班工时',d.summary.overtime_hours+'h','查询范围内','')}</div><section class="surface attendance-shell"><div class="surface-head"><h2>人员 × 日期考勤矩阵</h2><span class="badge blue">${start} 至 ${end}</span></div><table class="attendance-matrix"><thead><tr><th>员工 / 工号</th>${dates.map(day=>`<th>${day.slice(5)}</th>`).join('')}</tr></thead><tbody>${d.employees.map(employee=>`<tr><td><b>${esc(employee.name)}</b><br><small>${esc(employee.code)} · ${esc(employee.role)}</small></td>${dates.map(day=>{const record=map.get(`${employee.id}-${day}`);return `<td>${record?`<span class="attendance-state ${record.event_type}">${({normal:'正常',late:'迟到',absence:'缺勤',leave:'请假',overtime:'加班'}[record.event_type]||record.event_type)}</span>`:'—'}</td>`}).join('')}</tr>`).join('')||`<tr><td colspan="${dates.length+1}" class="empty">没有匹配的考勤记录</td></tr>`}</tbody></table></section>`;$('#attendanceSearch').onclick=()=>{const nextStart=$('#attendanceStart').value,nextEnd=$('#attendanceEnd').value;if(!nextStart||!nextEnd||nextStart>nextEnd)return toast('请选择有效的开始和结束日期',true);state.attendanceStart=nextStart;state.attendanceEnd=nextEnd;state.attendanceName=$('#attendanceName').value.trim();state.attendanceCode=$('#attendanceCode').value.trim();renderAttendanceDynamic()};$('#attendanceReset').onclick=()=>{state.attendanceStart='2026-08-01';state.attendanceEnd='2026-08-07';state.attendanceName='';state.attendanceCode='';renderAttendanceDynamic()}}
const renderAttendanceDynamicBase=renderAttendanceDynamic;renderAttendance=async function(){await renderAttendanceDynamicBase();const start=state.attendanceStart||'2026-08-01',end=state.attendanceEnd||'2026-08-07',data=await api(`/api/attendance/overview?start=${encodeURIComponent(start)}&end=${encodeURIComponent(end)}&name=${encodeURIComponent(state.attendanceName||'')}&code=${encodeURIComponent(state.attendanceCode||'')}`),daily=new Map((data.daily_summary||[]).map(item=>[`${item.employee_id}-${item.event_date}`,item])),dates=attendanceDateRange(start,end),employees=new Map(data.employees.map(item=>[item.code,item.id]));content.querySelectorAll('.attendance-matrix tbody tr').forEach(row=>{const code=row.querySelector('td')?.textContent.match(/FS\d+/)?.[0],employeeId=employees.get(code);if(!employeeId)return;Array.from(row.querySelectorAll('td')).slice(1).forEach((cell,index)=>{const item=daily.get(`${employeeId}-${dates[index]}`);cell.innerHTML=item?`<div class="attendance-metrics"><span>出勤 ${item.attendance_hours}h</span><span>请假 ${item.leave_hours}h</span><span>迟到 ${item.late_count}次</span><span>加班 ${item.overtime_hours}h</span></div>`:'<span class="attendance-empty">—</span>'})});if(!['admin','manager','hr'].includes(state.user.role))return;content.insertAdjacentHTML('beforeend',renderApprovalRequests(data.approval_requests||[]))};
function scheduleMatrix(shifts,start,end){const dates=scheduleDates(start,end),byEmployee=new Map();shifts.forEach(shift=>{const key=shift.employee_id;if(!byEmployee.has(key))byEmployee.set(key,{name:shift.employee_name,code:shift.employee_code,role:shift.role,shifts:{}});byEmployee.get(key).shifts[shift.start_at.slice(0,10)]=shift});if(!byEmployee.size)return '<div class="empty">当前月份暂无已发布班次。</div>';return `<table class="schedule-matrix monthly"><thead><tr><th class="employee-heading">员工 / 技能</th>${dates.map(date=>`<th>${['周日','周一','周二','周三','周四','周五','周六'][date.getDay()]} <small>${date.getMonth()+1}/${date.getDate()}</small></th>`).join('')}</tr></thead><tbody>${[...byEmployee.values()].map(employee=>`<tr><td class="schedule-employee"><span class="avatar">${esc(employee.name.slice(0,1))}</span><span><b>${esc(employee.name)}</b><small>${esc(employee.role)} · ${esc(employee.code)}</small></span></td>${dates.map(date=>{const key=`${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`,shift=employee.shifts[key];if(!shift||scheduleShiftType(shift)==='rest')return '<td class="schedule-rest"></td>';const type=scheduleShiftType(shift);return `<td class="schedule-shift ${type}"><b>${esc(shift.start_at.slice(11,16))}–${esc(shift.end_at.slice(11,16))}</b><small>${esc(type==='evening'?'晚班':type==='split'?'午班':'早班')} · ${esc(shift.role)}</small></td>`}).join('')}</tr>`).join('')}</tbody></table>`}
init();
document.addEventListener('click',event=>{const button=event.target.closest('#attendanceSearch,#attendanceReset');if(!button)return;event.preventDefault();event.stopImmediatePropagation();if(button.id==='attendanceReset'){state.attendanceStart='2026-08-01';state.attendanceEnd='2026-08-07';state.attendanceName='';state.attendanceCode=''}else{const start=$('#attendanceStart')?.value,end=$('#attendanceEnd')?.value;if(!start||!end||start>end){toast('请选择有效的开始和结束日期',true);return}state.attendanceStart=start;state.attendanceEnd=end;state.attendanceName=$('#attendanceName')?.value.trim()||'';state.attendanceCode=$('#attendanceCode')?.value.trim()||''}renderAttendance()},{capture:true});
